                'a1' => 'Le Luxembourg applique 4 taux : standard 17% (la majorité des opérations), intermédiaire 14% (vins, combustibles), réduit 8% (gaz, électricité, coiffure), super-réduit 3% (alimentation, livres, médicaments, transports). Ces taux sont en vigueur depuis le 1er janvier 2024 (le standard est revenu de 16% à 17%).',
                'q2' => 'Quand appliquer le taux standard de 17% ?',
                'a2' => 'Le taux standard s\'applique à toutes les opérations imposables qui ne relèvent pas explicitement d\'un autre taux : prestations de services, ventes de biens, conseil, location de matériel professionnel, etc. C\'est le taux par défaut.',
                'q3' => 'Comment calcule-t-on le montant HT à partir du TTC ?',
                'a3' => 'Pour passer du TTC au HT : montant HT = montant TTC ÷ (1 + taux/100). Exemple : 1000 € TTC à 17% → 1000 ÷ 1,17 = 854,70 € HT. La TVA est donc 1000 - 854,70 = 145,30 €.',
                'q4' => 'Faktur.lu calcule-t-il automatiquement la TVA ?',
                'a4' => 'Oui, faktur.lu détecte automatiquement le bon taux selon le type de prestation et l\'applique sur chaque ligne de facture. Les opérations B2B intracommunautaires sont automatiquement marquées en autoliquidation (article 21 LIVA) avec validation VIES en temps réel du numéro de TVA client.',
            ],
        ],
