            'q2' => ['q' => 'Combien d\'utilisateurs peuvent travailler en parallèle ?', 'a' => 'Plan Pro : 5 utilisateurs (administrateurs et collaborateurs) + 3 comptables externes en lecture seule. Aucun surcoût par utilisateur. Si vous avez besoin de plus, contactez-nous.'],
