    'legal_terms_s1_title' => '1. Objet',
    'legal_terms_s1_p1' => 'Les présentes Conditions Générales d\'Utilisation et de Vente (ci-après "CGU/CGV") ont pour objet de définir les conditions dans lesquelles Alexandre Beaudier, exploitant le service faktur.lu (ci-après "le Prestataire"), fournit aux utilisateurs (ci-après "l\'Utilisateur" ou "le Client") un service de facturation en ligne.',
    'legal_terms_s1_p2' => 'L\'inscription et l\'utilisation du service impliquent l\'acceptation pleine et entière des présentes CGU/CGV.',

    'legal_terms_s2_title' => '2. Définitions',
    'legal_terms_s2_li1_label' => 'Service :',
    'legal_terms_s2_li1_text' => 'L\'application web faktur.lu permettant la création et la gestion de factures, devis, avoirs et le suivi du temps.',
    'legal_terms_s2_li2_label' => 'Utilisateur / Client :',
    'legal_terms_s2_li2_text' => 'Toute personne physique ou morale ayant créé un compte sur faktur.lu.',
    'legal_terms_s2_li3_label' => 'Compte :',
    'legal_terms_s2_li3_text' => 'L\'espace personnel de l\'Utilisateur accessible via ses identifiants.',
    'legal_terms_s2_li4_label' => 'Abonnement :',
    'legal_terms_s2_li4_text' => 'Formule payante donnant accès à des fonctionnalités étendues du Service.',
    'legal_terms_s2_li5_label' => 'Contenu :',
    'legal_terms_s2_li5_text' => 'Les données saisies par l\'Utilisateur (factures, clients, etc.).',

    'legal_terms_s3_title' => '3. Accès au service',
    'legal_terms_s3_1_title' => '3.1 Inscription',
    'legal_terms_s3_1_p' => 'L\'accès au Service nécessite la création d\'un compte. L\'Utilisateur doit fournir des informations exactes et complètes, notamment une adresse email valide.',
    'legal_terms_s3_2_title' => '3.2 Conditions d\'éligibilité',
    'legal_terms_s3_2_p' => 'Le Service est destiné aux professionnels (entreprises, indépendants, professions libérales). L\'Utilisateur déclare :',
    'legal_terms_s3_2_li1' => 'Être majeur et juridiquement capable',
    'legal_terms_s3_2_li2' => 'Agir dans le cadre de son activité professionnelle',
    'legal_terms_s3_2_li3' => 'Disposer des autorisations nécessaires pour utiliser le Service',
    'legal_terms_s3_3_title' => '3.3 Sécurité du compte',
    'legal_terms_s3_3_p' => 'L\'Utilisateur est responsable de la confidentialité de ses identifiants de connexion. Toute utilisation de son compte est réputée faite par lui. Il doit informer immédiatement faktur.lu de toute utilisation non autorisée.',

    'legal_terms_s4_title' => '4. Description du service',
    'legal_terms_s4_p' => 'faktur.lu est un logiciel de facturation en ligne (SaaS) conforme aux exigences luxembourgeoises et européennes, offrant notamment :',
    'legal_terms_s4_li1' => 'Création et gestion de factures, devis et avoirs',
    'legal_terms_s4_li2' => 'Gestion des clients et des contacts',
    'legal_terms_s4_li3' => 'Export FAIA conforme à l\'AED Luxembourg',
    'legal_terms_s4_li4' => 'Suivi du temps et génération de factures',
    'legal_terms_s4_li5' => 'Envoi de factures par email',
    'legal_terms_s4_li6' => 'Tableau de bord et statistiques',
    'legal_terms_s4_li7' => 'Accès comptable sécurisé',

    'legal_terms_s5_title' => '5. Abonnements et tarifs',
    'legal_terms_s5_1_title' => '5.1 Formules d\'abonnement',
    'legal_terms_s5_1_p' => 'Le Service propose plusieurs formules :',
    'legal_terms_s5_plan1_title' => 'Découverte (Gratuit)',
    'legal_terms_s5_plan1_desc' => 'Fonctionnalités limitées, idéal pour tester le service.',
    'legal_terms_s5_plan2_title' => 'Professionnel',
    'legal_terms_s5_plan2_desc' => 'Fonctionnalités complètes pour les indépendants et PME. Tarif affiché sur la page de tarification.',
    'legal_terms_s5_2_title' => '5.2 Tarifs',
    'legal_terms_s5_2_p1' => 'Les tarifs sont indiqués en euros hors taxes (HT) sur le site. La TVA applicable sera ajoutée au moment du paiement selon le taux en vigueur au Luxembourg (17%).',
    'legal_terms_s5_2_p2' => 'Le Prestataire se réserve le droit de modifier ses tarifs à tout moment. Les modifications de tarifs seront notifiées par email au moins 30 jours avant leur entrée en vigueur et s\'appliqueront au prochain renouvellement de l\'abonnement.',
    'legal_terms_s5_3_title' => '5.3 Durée et renouvellement',
    'legal_terms_s5_3_p' => 'Les abonnements sont souscrits pour une durée mensuelle ou annuelle selon le choix de l\'Utilisateur. Ils sont renouvelés automatiquement par tacite reconduction à l\'issue de chaque période, sauf résiliation conformément à l\'article 13.',
    'legal_terms_s5_4_title' => '5.4 Période d\'essai',
    'legal_terms_s5_4_p' => 'Une période d\'essai gratuite peut être proposée. À l\'issue de cette période, l\'abonnement devient payant sauf résiliation. L\'Utilisateur sera informé avant la fin de la période d\'essai.',

    'legal_terms_s6_title' => '6. Paiement',
    'legal_terms_s6_1_title' => '6.1 Moyens de paiement',
    'legal_terms_s6_1_p' => 'Le paiement s\'effectue par carte bancaire (Visa, Mastercard, American Express) via la plateforme sécurisée Stripe. Les transactions sont chiffrées et conformes aux normes PCI-DSS.',
    'legal_terms_s6_2_title' => '6.2 Facturation',
    'legal_terms_s6_2_p' => 'Une facture électronique est émise et disponible dans l\'espace client après chaque paiement. Elle peut également être envoyée par email sur demande.',
    'legal_terms_s6_3_title' => '6.3 Défaut de paiement',
    'legal_terms_s6_3_p' => 'En cas d\'échec du paiement, l\'Utilisateur sera notifié et disposera d\'un délai de 7 jours pour régulariser. Passé ce délai, l\'accès aux fonctionnalités payantes sera suspendu. Les données seront conservées pendant 30 jours supplémentaires avant suppression éventuelle.',
    'legal_terms_s6_4_title' => '6.4 TVA',
    'legal_terms_s6_4_p' => 'Pour les clients professionnels établis dans un autre État membre de l\'UE disposant d\'un numéro de TVA intracommunautaire valide, la TVA ne sera pas facturée (autoliquidation). Le Client devra alors déclarer la TVA dans son pays.',

    'legal_terms_s7_title' => '7. Droit de rétractation',
    'legal_terms_s7_warn_title' => 'Information importante pour les consommateurs',
    'legal_terms_s7_warn_p' => 'Conformément à l\'article L. 221-28 du Code de la consommation français et aux dispositions équivalentes du droit luxembourgeois, le droit de rétractation ne s\'applique pas aux contrats de fourniture de contenu numérique non fourni sur un support matériel dont l\'exécution a commencé avec l\'accord préalable exprès du consommateur.',
    'legal_terms_s7_p1' => 'En souscrivant à un abonnement payant, l\'Utilisateur reconnaît que :',
    'legal_terms_s7_li1' => 'Il demande expressément l\'exécution immédiate du service',
    'legal_terms_s7_li2' => 'Il renonce expressément à son droit de rétractation de 14 jours dès que l\'accès au service payant est activé',
    'legal_terms_s7_p2' => 'Toutefois, pour les abonnements annuels, un remboursement prorata temporis peut être accordé sur demande dans les 30 premiers jours suivant la souscription, sous réserve d\'une utilisation raisonnable du service.',

    'legal_terms_s8_title' => '8. Obligations de l\'utilisateur',
    'legal_terms_s8_p' => 'L\'Utilisateur s\'engage à :',
    'legal_terms_s8_li1' => 'Fournir des informations exactes lors de l\'inscription et les maintenir à jour',
    'legal_terms_s8_li2' => 'Utiliser le Service conformément à sa destination (facturation professionnelle)',
    'legal_terms_s8_li3' => 'Ne pas utiliser le Service à des fins illicites ou contraires à l\'ordre public',
    'legal_terms_s8_li4' => 'Conserver la confidentialité de ses identifiants de connexion',
    'legal_terms_s8_li5' => 'Respecter la législation fiscale et comptable applicable à son activité',
    'legal_terms_s8_li6' => 'Ne pas tenter de compromettre la sécurité ou le fonctionnement du Service',
    'legal_terms_s8_li7' => 'Ne pas revendre ou sous-licencier l\'accès au Service',

    'legal_terms_s9_title' => '9. Obligations de faktur.lu',
    'legal_terms_s9_1_title' => '9.1 Disponibilité du service',
    'legal_terms_s9_1_p1' => 'Le Prestataire s\'engage à mettre en oeuvre les moyens nécessaires pour assurer la disponibilité du Service 24h/24 et 7j/7, avec un objectif de disponibilité de 99,5% (hors maintenance programmée).',
    'legal_terms_s9_1_p2' => 'Les interruptions pour maintenance seront, dans la mesure du possible, programmées en dehors des heures ouvrables et annoncées préalablement.',
    'legal_terms_s9_2_title' => '9.2 Support',
    'legal_terms_s9_2_p_before' => 'Un support technique est disponible par email à',
    'legal_terms_s9_2_p_after' => '. Le délai de réponse varie selon la formule d\'abonnement.',
    'legal_terms_s9_3_title' => '9.3 Sécurité et sauvegarde',
    'legal_terms_s9_3_p' => 'Le Prestataire met en oeuvre des mesures de sécurité conformes aux standards de l\'industrie et effectue des sauvegardes régulières des données.',

    'legal_terms_s10_title' => '10. Données et propriété',
    'legal_terms_s10_1_title' => '10.1 Propriété des données',
    'legal_terms_s10_1_p' => 'L\'Utilisateur reste propriétaire de toutes les données qu\'il saisit dans le Service (factures, informations clients, etc.). Le Prestataire n\'acquiert aucun droit sur ces données.',
    'legal_terms_s10_2_title' => '10.2 Licence d\'utilisation',
    'legal_terms_s10_2_p' => 'L\'Utilisateur accorde au Prestataire une licence limitée pour traiter ses données uniquement dans le cadre de la fourniture du Service.',
    'legal_terms_s10_3_title' => '10.3 Export des données',
    'legal_terms_s10_3_p' => 'L\'Utilisateur peut à tout moment exporter ses données dans des formats standards (PDF, CSV, FAIA XML).',
    'legal_terms_s10_4_title' => '10.4 Protection des données',
    'legal_terms_s10_4_p_before' => 'Le traitement des données personnelles est régi par notre',
    'legal_terms_s10_4_link' => 'Politique de confidentialité',
    'legal_terms_s10_4_p_after' => '.',

    'legal_terms_s10_5_title' => '10.5 Sous-traitance RGPD (DPA)',
    'legal_terms_s10_5_p_before' => 'Lorsque l\'Utilisateur est responsable de traitement au sens du Règlement (UE) 2016/679 (RGPD) et que faktur.lu traite des données à caractère personnel pour son compte, les parties conviennent que l\'',
    'legal_terms_s10_5_link' => 'Accord de traitement des données (DPA)',
    'legal_terms_s10_5_p_after' => ', accessible à tout moment sur le site, fait partie intégrante des présentes CGU. En acceptant les CGU, l\'Utilisateur accepte également le DPA dans sa version en vigueur. Une signature manuscrite séparée peut être effectuée sur demande pour les Utilisateurs en ayant besoin pour leur propre conformité (notamment fiduciaires et clients soumis à audit).',

    'legal_terms_s11_title' => '11. Propriété intellectuelle',
    'legal_terms_s11_p1' => 'Le Service, incluant son code source, son interface, ses fonctionnalités, son design, ses marques et logos, est la propriété exclusive du Prestataire ou de ses partenaires.',
    'legal_terms_s11_p2' => 'L\'abonnement confère uniquement un droit d\'utilisation personnel, non exclusif et non transférable du Service pour la durée de l\'abonnement.',

    'legal_terms_s12_title' => '12. Limitation de responsabilité',
    'legal_terms_s12_1_title' => '12.1 Garanties',
    'legal_terms_s12_1_p' => 'Le Prestataire s\'engage à fournir le Service avec diligence. Toutefois, le Service est fourni "en l\'état" et le Prestataire ne garantit pas qu\'il répondra à tous les besoins spécifiques de l\'Utilisateur.',
    'legal_terms_s12_2_title' => '12.2 Limitation',
    'legal_terms_s12_2_p1' => 'La responsabilité du Prestataire est limitée aux dommages directs et ne pourra excéder le montant des sommes versées par l\'Utilisateur au cours des 12 derniers mois.',
    'legal_terms_s12_2_p2' => 'Le Prestataire ne saurait être tenu responsable :',
    'legal_terms_s12_2_li1' => 'Des dommages indirects (perte de chiffre d\'affaires, préjudice commercial, etc.)',
    'legal_terms_s12_2_li2' => 'De l\'exactitude des données saisies par l\'Utilisateur',
    'legal_terms_s12_2_li3' => 'De la conformité fiscale des factures émises par l\'Utilisateur',
    'legal_terms_s12_2_li4' => 'Des interruptions dues à des tiers (hébergeur, FAI, etc.)',
    'legal_terms_s12_2_li5' => 'Des cas de force majeure',
    'legal_terms_s12_3_title' => '12.3 Responsabilité de l\'Utilisateur',
    'legal_terms_s12_3_p' => 'L\'Utilisateur est seul responsable de la conformité de ses factures avec la réglementation fiscale applicable. Le Service est un outil facilitant la facturation mais ne constitue pas un conseil fiscal ou juridique.',

    'legal_terms_s13_title' => '13. Résiliation',
    'legal_terms_s13_1_title' => '13.1 Résiliation par l\'Utilisateur',
    'legal_terms_s13_1_p1' => 'L\'Utilisateur peut résilier son abonnement à tout moment depuis son espace client. La résiliation prendra effet à la fin de la période en cours. L\'Utilisateur conserve l\'accès au Service jusqu\'à cette date.',
    'legal_terms_s13_1_p2' => 'Les sommes déjà versées ne sont pas remboursables, sauf disposition contraire prévue à l\'article 7.',
    'legal_terms_s13_2_title' => '13.2 Résiliation par le Prestataire',
    'legal_terms_s13_2_p' => 'Le Prestataire peut résilier l\'abonnement en cas de :',
    'legal_terms_s13_2_li1' => 'Violation des présentes CGU',
    'legal_terms_s13_2_li2' => 'Défaut de paiement non régularisé',
    'legal_terms_s13_2_li3' => 'Utilisation frauduleuse ou abusive du Service',
    'legal_terms_s13_2_li4' => 'Cessation d\'activité du Service (avec préavis de 3 mois)',
    'legal_terms_s13_3_title' => '13.3 Conséquences de la résiliation',
    'legal_terms_s13_3_p' => 'À la résiliation, l\'Utilisateur dispose de 30 jours pour exporter ses données. Passé ce délai, les données pourront être supprimées, sous réserve des obligations légales de conservation.',

    'legal_terms_s14_title' => '14. Modifications des CGU',
    'legal_terms_s14_p1' => 'Le Prestataire se réserve le droit de modifier les présentes CGU. Les modifications seront notifiées par email et/ou par affichage sur le Service au moins 30 jours avant leur entrée en vigueur.',
    'legal_terms_s14_p2' => 'L\'utilisation continue du Service après l\'entrée en vigueur des modifications vaut acceptation des nouvelles CGU. En cas de désaccord, l\'Utilisateur peut résilier son abonnement.',

    'legal_terms_s15_title' => '15. Droit applicable et juridiction',
    'legal_terms_s15_p1' => 'Les présentes CGU sont régies par le droit luxembourgeois.',
    'legal_terms_s15_p2' => 'En cas de litige, les parties s\'efforceront de trouver une solution amiable. À défaut, les tribunaux de Luxembourg seront seuls compétents.',
    'legal_terms_s15_p3_label' => 'Médiation :',
    'legal_terms_s15_p3_text' => 'Conformément à la réglementation européenne, en cas de litige non résolu, le consommateur peut recourir gratuitement au service de médiation. Plateforme de règlement en ligne des litiges :',

    'legal_terms_s16_title' => '16. Contact',
    'legal_terms_s16_p' => 'Pour toute question concernant ces CGU :',
