    'legal_cookies_s1_title' => '1. Qu\'est-ce qu\'un cookie ?',
    'legal_cookies_s1_p1' => 'Un cookie est un petit fichier texte déposé sur votre appareil (ordinateur, tablette, smartphone) lors de la visite d\'un site web. Il permet au site de mémoriser des informations sur votre visite, comme vos préférences de langue ou votre statut de connexion.',
    'legal_cookies_s1_p2' => 'Les cookies peuvent être déposés par le site que vous visitez ("cookies propriétaires") ou par des services tiers ("cookies tiers").',
