    'recurring_invoice_how_p1_html' => 'Une récurrence est un <strong>modèle</strong> qui génère automatiquement de nouvelles factures à intervalles réguliers (hebdomadaire, mensuel, trimestriel ou annuel).',
    'recurring_invoice_how_p2_html' => 'Chaque jour à <strong>06:00</strong>, le système vérifie les récurrences <strong>actives</strong> dont la prochaine date est arrivée et crée la facture correspondante. Selon les options choisies :',
